    params.sort_by = sortBy;
  }
  if (sortOrder) {
    params.sort_order = sortOrder;
  }

  const response = await apiClient.get<ContractGeneration[]>(
    `${BASE_URL}/contracts/approved`,
    { params }
  );
  return response.data;
},

